() => {
  const selects = Array.from(document.querySelectorAll('select[name="unitMeasure"]'));
  const results = [];
  selects.forEach((s, idx) => {
    s.value = 'Per Item';
    s.dispatchEvent(new Event('input', { bubbles: true }));
