    let current = el;
    let heading = '';
    while (current && current !== document.body) {
      let h = current.querySelector('h1, h2, h3, h4, h5, .a-size-medium, .a-size-large');
      if (h) {
        heading = h.innerText;
        break;
      }
      current = current.parentElement;
    }
    return {
      index: i,
      heading: heading,
      sectionId: parentSection ? parentSection.id : null,
      val: el.value
    };
  });
}","pageId":11,"toolSummary":"Find section headings for each row"}

