{"function":"() => {
  const ppos = Array.from(document.querySelectorAll('input[name="pricePerOrder"]'));
  return ppos.map((el, idx) => {
    // Find closest container and walk backwards to previous headers
    let container = el.closest('table') || el.closest('.a-box');
    let prevHeader = '';
    let node = container;
    while (node && !prevHeader) {
      let sibling = node.previousElementSibling;
      while (sibling) {
        if (sibling.innerText && (sibling.innerText.includes('标准配送') || sibling.innerText.includes('加急配送'))) {
          prevHeader = sibling.innerText.split('\n')[0];
          break;
        }
        sibling = sibling.previousElementSibling;
      }
      node = node.parentElement;
    }
    return {
      idx,
      prevHeader,
      pricePerOrder: el.value,
      unitPrice: document.querySelectorAll('input[name="unitPrice"]')[idx]?.value,
      unitMeasure: document.querySelectorAll('select[name="unitMeasure"]')[idx]?.value
    };
  });
}","pageId":11,"toolSummary":"Match input rows to shipping section headers"}

